ref_dict.thm:enrich_rev:
\begin{theorem} \label{thm:enrich_rev}
	Let $\C$ be a finitely cancellative semiadditive CD category, and suppose
	\begin{itemize}
		\item $\mu : \ind \to \augS$ is finite
		\item $\phi : \augS \to \augS$ is a deterministic involution
		\item $\alpha : \augS \to \ind$ is a probability
		\item $\rx = \frac{\dif (\phi \circ \mu)}{\dif \mu}$ is a Radon--Nikodym derivative.
	\end{itemize}
	Then $\Pmh$ defined in \eqref{eq:mh-kernel-abstract} is $\mu$-reversible if and only if the following ``balancing condition'' holds:
	\begin{equation} \label{eq:algebraic-balancing-condition-synthetic}
		\alpha = (\alpha \circ \phi) \ast \rx \qquad \text{$\mu$-almost everywhere.}
	\end{equation}
\end{theorem}

ref_dict.thm:lebesgue-decomposition-involution:
\begin{theorem} \label{thm:lebesgue-decomposition-involution}
	Let $\C$ be a zero-sum-free $\CMon$-enriched category.
	Let $\P : \tarS \to \sndS$ and $\phi : \sndS \to \sndS$ be morphisms in $\C$, where $\phi$ is an involution, and suppose $(\P_\ac, \P_\si)$ is a $(\phi \circ \P)$-decomposition of $\P$.
	Then we have both the following:
	\begin{enumerate}
		\item $\P_\ac \equiv \phi \circ \P_\ac$
		\item $\P_\si \perp \phi \circ \P_\si$
	\end{enumerate}
\end{theorem}

ref_dict.cor:skew:
\begin{corollary} \label{cor:skew}
	Given the setup of Corollary \ref{cor:andrieu2020}, suppose we also have a measurable involution $s:\augS \to \augS$ that is $\mu$-invariant.
	Then $\Pi_{\mathrm{sMH}}$ is $(\mu,s)$-reversible if and only if the balancing condition \eqref{eq:andrieu2020-balancing-condition} holds.
\end{corollary}

