\begin{prop}\label{triangles}
Let $\cs$ be a triangulated category with a full and strong exceptional sequence as in \eqref{eq:S}. Then $\cs$ is algebraic and is uniquely determined, up to isomorphism in $\Ht$. Moreover, extending $A\mor f B\mor g C$ to an octahedron, for which we use the same notation of \eqref{eq:oct} and \eqref{eq:sets}, the following holds.
\begin{enumerate}
\item\label{triangles1} Up to isomorphism, every indecomposable object of $\cs$ is of the form $\sh[n]X$, for a unique $X\in\I$ and a unique $n\in\ZZ$. 
\item\label{triangles2} The indecomposable objects of $\cs$ are exceptional and, up to shift and isomorphism, the only nonzero morphisms between non-isomorphic indecomposable objects are those in $\J$. More precisely, given distinct $X,Y\in\I$ and $n\in\ZZ$, we have $\cs(X,\sh[n]Y)=0$ except in the following cases:
\begin{gather*}
\cs(A,B)=\K f, \qquad \cs(A,C)=\K h, \qquad \cs(B,C)=\K g, \qquad \cs(B,D)=\K f', \\
\cs(B,E)=\K l, \qquad \cs(C,E)=\K h', \qquad \cs(C,F)=\K g', \qquad \cs(D,E)=\K k, \\
\cs(D,\sh A)=\K f'', \qquad \cs(E,F)=\K k', \qquad \cs(E,\sh A)=\K h'', \\
\cs(E,\sh B)=\K l', \qquad \cs(F,\sh B)=\K g'', \qquad \cs(F,\sh D)=\K k''.
\end{gather*}
The composition of morphisms is completely determined by the following relations:
\begin{equation}\label{eq:comp}
\begin{split}
f''=h''\comp k, \qquad g'=k'\comp h', \qquad h=g\comp f, \qquad k''=\sh{f'}\comp g'', \qquad l=h'\comp g=k\comp f', \\
l'=\sh f\comp h''=g''\comp k', \qquad f'\comp f=0, \qquad h''\comp h'=0, \qquad \sh g\comp g''=0, \qquad k'\comp k=0.
\end{split}
\end{equation}
\item\label{triangles3} A triangle in $\cs$ is distinguished if and only if it is (isomorphic to) a finite direct sum of triangles, each of which, up to rotation, is either one among \eqref{eq:tri1}, \eqref{eq:tri2}, \eqref{eq:tri3}, \eqref{eq:tri4}, \eqref{eq:tri5}, \eqref{eq:tri6}(in particular, the octahedron \eqref{eq:oct} is good), or  $\tri X{\id}X{}0{}$ for some $X\in\I$ .
\end{enumerate}
\end{prop}

ref_dict.KS:
\begin{lem}\label{KS}
$\cs$ is a Krull-Schmidt category.\footnote{An additive category is Krull-Schmidt if every object is a finite direct sum of objects with local endomorphism rings. In a Krull-Schmidt category an object is indecomposable if and only if its endomorphism ring is local, and every object is in an essentially unique way a finite direct sum of indecomposable objects.} Moreover, if $\cs$ is algebraic, then the following is true.
\begin{enumerate}
    \item $\cs\iso\Db(\fMod A)$ in $\Ht$, where $A:=\End_\cs(\oplus_{i=1}^n\E_i)$.
    \item $\cs$ has a strongly unique enhancement and an enhancement of $\cs$ is given by $\Pretr(\ce)$ (where $\ce$ is regarded as a dg category concentrated in degree $0$).
    \item If $\ce$ is of the form $\K[Q]$ for some quiver $Q$, then $A$ is left hereditary.
\end{enumerate}
\end{lem}

