\begin{gather*}
\cs(A,B)=\K f, \qquad \cs(A,C)=\K h, \qquad \cs(B,C)=\K g, \qquad \cs(B,D)=\K f', \\
\cs(B,E)=\K l, \qquad \cs(C,E)=\K h', \qquad \cs(C,F)=\K g', \qquad \cs(D,E)=\K k, \\
\cs(D,\sh A)=\K f'', \qquad \cs(E,F)=\K k', \qquad \cs(E,\sh A)=\K h'', \\
\cs(E,\sh B)=\K l', \qquad \cs(F,\sh B)=\K g'', \qquad \cs(F,\sh D)=\K k''.
\end{gather*}
The composition of morphisms is completely determined by the following relations:
\begin{equation}\label{eq:comp}
\begin{split}
f''=h''\comp k, \qquad g'=k'\comp h', \qquad h=g\comp f, \qquad k''=\sh{f'}\comp g'', \qquad l=h'\comp g=k\comp f', \\
l'=\sh f\comp h''=g''\comp k', \qquad f'\comp f=0, \qquad h''\comp h'=0, \qquad \sh g\comp g''=0, \qquad k'\comp k=0.
\end{split}
\end{equation}
\item\label{triangles3} A triangle in $\cs$ is distinguished if and only if it is (isomorphic to) a finite direct sum of triangles, each of which, up to rotation, is either one among \eqref{eq:tri1}, \eqref{eq:tri2}, \eqref{eq:tri3}, \eqref{eq:tri4}, \eqref{eq:tri5}, \eqref{eq:tri6}(in particular, the octahedron \eqref{eq:oct} is good), or  $\tri X{\id}X{}0{}$ for some $X\in\I$ .
\end{enumerate}
\end{prop}

Writing $f$ and $g$ for generators of the one-dimensional spaces $\cat S(A,B)$ and $\cat S(B,C)$, “every distinguished triangle in $\cat S$ arises from the four distinguished triangles appearing in an octahedron extending $f$ and $g$, together with the two additional … triangles associated with this octahedron.”
\item Define an octahedron to be \emph{good} if “these two extra triangles are distinguished.”
\item Deduce the classification:
\begin{cor}\label{cor:bij}
Let $\ct$ be a (small) triangulated category. There is a natural bijection between $\Ht(\cs,\ct)$ and the set of isomorphism classes of good octahedra in $\ct$.
\end{cor}
\item Apply this to produce a non-liftable functor: using the preceding classification, one applies the following proposition.

\begin{prop}\label{nolift}
Let $\cs$ be as in the statement of \autoref{thmalg} and let $\ct$ be a triangulated category with a strongly unique enhancement. If there exist two non isomorphic good octahedra extending the same pair of composable morphisms in $\ct$, then there exists an exact functor $\cs\to\ct$ without a lift.  
\end{prop}

\item Obtain the needed pair of non-isomorphic good octahedra by adapting K"unzer’s construction: one uses the following proposition.

\begin{prop}\label{prop:oct}
The two composable morphisms
\begin{equation}\label{eq:setup1}
A:=R_3\mor{f:=x^1}B:=R_3\mor{g:=x^1}C:=R_3
\end{equation}
can be extended to two non-isomorphic good octahedra in $\Dbz(\fMod R)$.
Using the notation of \eqref{eq:oct}, the first octahedron is given by:
\begin{equation}\label{eq:oct3}
\begin{gathered}
F=D=\sh{R_1}\oplus R_1, \qquad E=\sh{R_2}\oplus R_2,\\
f'=\Bigl(\begin{smallmatrix}
y \\
x^0
\end{smallmatrix}\Bigr),
\qquad h'=\Bigl(\begin{smallmatrix}
y \\
x^0
\end{smallmatrix}\Bigr),
\qquad g''=(\begin{smallmatrix}
-\sh{x^2} &\quad y
\end{smallmatrix}), \qquad h''=(\begin{smallmatrix}
-\sh{x^1} &\quad y
\end{smallmatrix}), 
\end{gathered}
\end{equation}
and 
\begin{gather}\label{eq:oct3b}
k=\Bigl(\begin{smallmatrix}
\sh{x^1} & 0\\
0 & x^1
\end{smallmatrix}\Bigr), \qquad k'=\Bigl(\begin{smallmatrix}
\sh{x^0} & 0\\
0 & x^0
\end{smallmatrix}\Bigr)
\end{gather}
(the other morphisms are determined by composition). The second octahedron is given by \eqref{eq:oct3} and
\begin{equation}\label{eq:octdata2}
\tilde{k}=\Big(\begin{smallmatrix}
\sh{x^1} & y \\
0 & x^1
\end{smallmatrix}\Bigr), \qquad \tilde{k}'=\Bigl(\begin{smallmatrix}
\sh{x^0} & -y \\
0 & x^0
\end{smallmatrix}\Bigr).
\end{equation}
\end{prop}

This yields the functor $\cat S\to\D^b(\Bbbk[x]\text{-}\mathrm{mod})$ with essential image in $\D_0^b(\Bbbk[x]\text{-}\mathrm{mod})$ and “which does not admit a lift.”
\end{itemize}

Finally, to prove the main theorem, one applies this algebraic non-liftability together with the identification “Fourier--Mukai if and only if it has a (dg) lift.” The reference to \autoref{sec:thmgeo} is used only to indicate that this is carried out later.

theorem.content:
\label{the theorem in introduction}
For all $0 \leq j \leq \ell \leq k,\; k\geq 1$, there exists a strictly ergodic system which admits the following:
\begin{enumerate}
    \item $Z_k$ is a nontrivial extension of $Z_{k-1}$
    \item $Z_i$ is topologically isomorphic to $X_i$ for all $0 \leq i \leq j$
    \item $Z_i$ is not measurably isomorphic to $X_i$ for all $j+1 \leq i \leq k$
    \item $X_i$ is topologically isomorphic to $X_{i+1}$ for all $i \geq \ell$.

\end{enumerate}
Furthermore, for every minimal, ergodic, and non-weak mixing $(X,\mu,T)$ there exist $j,\ell$, and $k$, such that $X$ satisfies properties (1)-(4).

