\begin{theorem} \label{thm2}
  Let $\kappa = 0$, and let $\Omega \subset \mathbb{R}^3$ be a bounded domain with smooth boundary. Assume that \eqref{phi} holds and that $S \in C^2([0,\infty))$ satisfies condition~\eqref{S} with $\alpha > \frac{1}{3}$. Then, for any initial data $n_0$ and $u_0$ fulfilling \eqref{initial}, the problem \eqref{1} under the boundary conditions \eqref{bdry} possesses a global classical solution $(n, c, u, P)$ satisfying
\begin{equation*}
    \begin{cases}
        n \in C^0(\bar{\Omega} \times [0,\infty)) \cap C^{2,1}(\bar{\Omega} \times (0,\infty)), \\
        c \in C^{2,0}(\bar{\Omega} \times (0,\infty)), \\
        u \in C^0([0,\infty); D(A^\beta)) \cap C^{2,1}(\bar{\Omega} \times (0,\infty); \mathbb{R}^3), \\
        P \in C^{1,0}(\bar{\Omega} \times (0,\infty)),
    \end{cases}
\end{equation*}
with $n$ and $c$ remaining positive in $\bar{\Omega} \times (0, \infty)$. Moreover, there exists a constant $C > 0$ such that
\begin{align} \label{thm2-1}
    \| n(\cdot,t) \|_{L^\infty(\Omega)} + \| c(\cdot,t) \|_{W^{1,\infty}(\Omega)} + \| u(\cdot,t) \|_{L^\infty(\Omega)} \leq C \quad \text{for all } t > 0.
\end{align}

\end{theorem}

