\label{thm1_1}
Let $n \geq 3$ and $\Omega=B_R(0) \subset \mathbb{R}^n$ with some $R>0$. Assume that $u_0$ and $w_0$ are radially symmetric that satisfy \begin{align}\label{eq1.1}
\nu_0, w_0 \in  W^{1,\infty}(\overline{\Omega}) \text{ are positive }.
\end{align}
Suppose that \begin{align}\label{f}
 f(|\nabla v|^2)=(1+|\nabla v|^2)^{-\frac{p}{2}}
\end{align}
and
\begin{align}\label{g}
 g(|\nabla z|^2)=(1+|\nabla z|^2)^{-\frac{q}{2}}.
\end{align}
hold with $p,q \in \mathbb{R} $ satisfying
\begin{align}\label{pq}
p< \frac{n-2}{n-1}\quad \text{and} \quad  q< \frac{n-2}{n-1}.
\end{align}
Then, there exist functions $M_1(r), M_2(r) \in C^0([0, R])$ such that if $u_0$, $w_0$ satisfy 
\begin{align}\label{eq1.8}
\int_{B_r(0)} u_0  \mathrm{~d}x \geq M_1(r),\quad \int_{B_r(0)} w_0  \mathrm{~d}x \geq M_2(r) ,\quad  r\in(0,R),
\end{align}
the corresponding solution of
\begin{align}\label{eq1.1.0}
\begin{cases}\nu_t = \Delta u -  \nabla \cdot \left(uf(|\nabla v|^2)\nabla v\right), & x \in \Omega, \ t > 0, \\ 
0 = \Delta v - \mu_w + w, \quad \mu_{w}=f_{\Omega} w, & x \in \Omega, \ t > 0, \\ 
w_t = \Delta w -  \nabla \cdot \left(w g(|\nabla z|^2) \nabla z\right), & x \in \Omega, \ t > 0, \\ 
0 = \Delta z - \mu_u + u, \quad \mu_{u}=f_{\Omega} u, & x \in \Omega, \ t > 0,\\
\frac{\partial u}{\partial \nu} = \frac{\partial v}{\partial \nu} = \frac{\partial w}{\partial \nu} = \frac{\partial z}{\partial \nu} = 0, & x \in \partial \Omega, \ t > 0, \\
u(x, 0) = u_0(x), \quad w(x, 0) = w_0(x), & x \in \Omega,
\end{cases}
\end{align}
blows up in finite time.

